import{_ as l,o as i,c as t,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2018-FEB-07 -- Ceph Developer Monthly","description":"","frontmatter":{"title":"2018-FEB-07 -- Ceph Developer Monthly","date":"2018-02-13T00:00:00.000Z","updated":"2018-02-13T00:00:00.000Z","tags":["Ceph","Dashboard","OpenStack Swift","Ceph Messenger","Cluster Replication"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-FEB-07_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2018/2018-FEB-07_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),s={name:"posts/2018/2018-FEB-07_-_-_Ceph_Developer_Monthly.md"};function o(r,e,a,n,_,h){return i(),t("div",null,[...e[0]||(e[0]=[p("<p>2018年2月7日，Ceph开发者月度会议在德国举行，会议主要讨论了以下几个关键议题：</p><ol><li><p><strong>Dashboard v2</strong>：</p><ul><li>自动化团队正在开发新的Dashboard v2，旨在替代现有版本。</li><li>使用Angular 2作为前端框架，后端采用CherryPy，集成到Manager中。</li><li>目前后端开发已完成，前端页面开发正在进行中，包括健康页面等。</li><li>计划下周结束前提交可审查的代码，并计划与监控等功能集成。</li></ul></li><li><p><strong>OpenStack Swift与Ceph的集成</strong>：</p><ul><li>自动化团队正在开发OpenStack Swift与Ceph的集成。</li><li>使用Ansible进行部署，不使用SaltStack或其他工具。</li><li>计划集成自动化监控功能，但需要手动设置图表和配置Dashboard。</li></ul></li><li><p><strong>Ceph Messenger v2</strong>：</p><ul><li>Messenger v2正在进行开发，包括身份验证和传输加密。</li><li>计划使用GSSAPI进行身份验证和加密，支持Kerberos和其他认证协议。</li><li>目前正在进行Kerberos的集成工作。</li></ul></li><li><p><strong>Ceph集群级别复制</strong>：</p><ul><li>讨论了集群级别复制的架构和实现细节。</li><li>使用日志条目和操作缓存来管理复制操作。</li><li>引入了新的模块来处理复制工作，讨论了复制暂停和恢复机制。</li></ul></li></ol><p>会议行动计划包括：</p><ul><li>自动化团队继续开发Dashboard v2和OpenStack Swift与Ceph的集成。</li><li>Ceph社区成员继续讨论和改进集群级别复制的实现。</li><li>Messenger v2团队继续进行身份验证和加密的集成工作。</li></ul><p>会议还讨论了Ceph社区的最新动态和未来发展方向。</p><p>[改进后的总结中可能遗漏或需要更正的信息]</p><ul><li>原始字幕内容中提到OpenStack Swift与Ceph的集成使用Ansible进行部署，但未提及是否集成自动监控功能。</li><li>原始字幕中提到Ceph Messenger v2使用GSSAPI进行身份验证和加密，但未提及支持的具体认证协议。</li><li>原始字幕中提到Ceph集群级别复制的实现细节，但未提及如何处理复制暂停和恢复机制。</li></ul><p>[改进后的总结内容结束]</p>",8)])])}const c=l(s,[["render",o]]);export{d as __pageData,c as default};
